PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "electrical_building_schema" (
            row_id INTEGER PRIMARY KEY AUTOINCREMENT,
            "Hierarchy" TEXT NOT NULL,
            "Supply From" TEXT,
            "Equipment ID" TEXT NOT NULL,
            "Building" TEXT NOT NULL,
            "Amperage Rating" TEXT,
            "Amperage Rating (UoM)" TEXT,
            "Power Rating" TEXT,
            "Power Rating (UoM)" TEXT,
            "Voltage Rating" TEXT,
            "Voltage Rating (UoM)" TEXT,
            "ambigous" TEXT,
            "sld_extract_run_id" TEXT DEFAULT "",
            "sld_ai_extract_payload" TEXT DEFAULT ""
        , new_draw TEXT DEFAULT "TRUE", ID_check TEXT DEFAULT "", matching_check INTEGER DEFAULT 0, source_pdf TEXT DEFAULT "", created_at TEXT DEFAULT "", "Wire Rating" TEXT DEFAULT "", "Wire Rating (UoM)" TEXT DEFAULT "");
COMMIT;
